  /** SourceFile paths that draw this layer (usually one). */
  files?: string[];
  /** Format of the files. */
  format?: "gerber" | "excellon" | "odb" | "ipc2581" | "svg" | "other";
  /** Gerber X2 file polarity. */
  polarity?: "positive" | "negative";
  /** Raw Gerber X2 %TF.FileFunction (or ODB++ layer type). */
  function?: string | null;
  /** Drill layers: plated (PTH) or not (NPTH); null when mixed. */
