  /** Assembly technology. */
  mount?: "smd" | "tht" | "other" | null;
  /** False for DNP (do not populate). */
  populate?: boolean;
  /** Listed in the BOM. */
  in_bom?: boolean;
  /** Listed in placement (pick-and-place) files. */
